// Procesar y formatear resultado del health check REST API
const items = $input.all();
const item = items.length > 0 ? items[0] : null;
const json = (item && item.json) ? item.json : {};
const error = (item && item.error) ? item.error : null;
const timestamp = new Date().toISOString();

let statusCode;
let hasError = false;

// Verificar si hay error: si error existe Y tiene propiedades, ES ERROR
const errorExists = error && (typeof error === 'object' ? Object.keys(error).length > 0 : true);
const jsonErrorExists = json && typeof json === 'object' && 'error' in json && json.error && (typeof json.error === 'object' ? Object.keys(json.error).length > 0 : true);

if (!item) {
  statusCode = 'TIMEOUT/NO_RESPONSE';
  hasError = true;
} else if (errorExists) {
  hasError = true;
  statusCode = (error && typeof error === 'object' && 'code' in error) ? error.code : 'ERROR';
} else if (jsonErrorExists) {
  hasError = true;
  statusCode = (json.error && typeof json.error === 'object' && 'code' in json.error) ? json.error.code : 'ERROR';
} else {
  statusCode = (json && typeof json === 'object' && 'statusCode' in json) ? json.statusCode : 
               ((json && typeof json === 'object' && 'code' in json) ? json.code : 200);
  if (typeof statusCode === 'string') {
    hasError = true;
  } else if (typeof statusCode === 'number') {
    hasError = statusCode < 200 || statusCode >= 400;
  }
}

const isOk = !hasError;

const estado = isOk ? 'exito' : 'error';
const nombreServicio = 'REST API';
const puerto = 3000;
const url = 'http://host.docker.internal:3000/up';
const errorMsg = (error && typeof error === 'object' && 'message' in error) ? error.message : 
                 ((json && typeof json === 'object' && 'error' in json) ? json.error : 
                 ((json && typeof json === 'object' && 'message' in json) ? json.message : 
                 (hasError ? 'Servicio no disponible o timeout' : null)));

// Construir mensaje descriptivo
let mensaje = `[${timestamp}] Health Check ${nombreServicio}\n`;
mensaje += `===========================================\n`;
mensaje += `${isOk ? 'OK' : 'ERROR'} ${nombreServicio} (puerto ${puerto}): ${isOk ? 'OK' : 'ERROR'}\n`;
mensaje += `   Status: ${statusCode}\n`;
if (!isOk && errorMsg) {
  mensaje += `   Error: ${errorMsg}\n`;
}
mensaje += `   URL: ${url}\n`;
mensaje += `===========================================\n`;

return {
  json: {
    tipo: 'health-check',
    mensaje: mensaje,
    estado: estado,
    fecha_ejecucion: timestamp,
    servicio: 'rest',
    nombre_servicio: nombreServicio,
    puerto: puerto,
    statusCode: statusCode,
    error: errorMsg,
    url: url
  }
};

